<script setup lang="ts">
/**
 * Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, ref, useId, watch } from 'vue'

import * as zag from '@zag-js/combobox'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, composingKey, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/overlays/command.module.css'
import Kbd from '../structure/Kbd.vue'
import Skeleton from '../structure/Skeleton.vue'
import type { CommandItem } from './Command.vue'

export interface CommandPanelProps {
  items: CommandItem[]
  placeholder: string
  escapeHint: string
  filter: 'contains' | false
  loading: boolean
  emptyMessage: string
}

defineOptions({ name: 'CommandPanel', inheritAttrs: false })

const props = defineProps<CommandPanelProps>()
const emit = defineEmits<{ queryChange: [query: string]; command: [] }>()
const uid = useId()
const query = ref('')
const collator = computed(
  () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
)
const needle = computed(() => query.value.normalize('NFC'))
const matches = computed(
  () => (item: CommandItem) =>
    ((text: string) =>
      needle.value === '' ||
      Array.from({ length: Math.max(0, text.length - needle.value.length + 1) }, (_, at) =>
        text.slice(at, at + needle.value.length),
      ).some((part) => collator.value.compare(part, needle.value) === 0))(
      (item.keywords === undefined
        ? item.label
        : `${item.label} ${item.keywords.join(' ')}`
      ).normalize('NFC'),
    ),
)
const shown = computed(() =>
  props.filter === false ? props.items : props.items.filter((item) => matches.value(item)),
)
const runs = computed(() =>
  shown.value.reduce(
    (into, item) => (
      item.group !== undefined && into.at(-1)?.[0]?.group === item.group
        ? into.at(-1)?.push(item)
        : into.push([item]),
      into
    ),
    [] as CommandItem[][],
  ),
)
const firstEnabled = computed(() => shown.value.find((item) => item.disabled !== true)?.id)
const showEmpty = computed(() => !props.loading && shown.value.length === 0)
const announcement = computed(() =>
  props.loading
    ? 'Loading commands…'
    : shown.value.length === 0
      ? props.emptyMessage
      : `${shown.value.length} commands`,
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    collection: zag.collection({
      items: shown.value,
      itemToValue: (item) => item.id,
      itemToString: (item) => item.label,
      isItemDisabled: (item) => item.disabled === true,
    }),
    open: true,
    disableLayer: true,
    value: [],
    closeOnSelect: false,
    selectionBehavior: 'preserve' as const,
    allowCustomValue: true,
    inputBehavior: 'autohighlight' as const,
    placeholder: props.placeholder,
    onInputValueChange: (details) => {
      ;((query.value = details.inputValue), emit('queryChange', details.inputValue))
    },
    onSelect: (details) => {
      ;(props.items.find((item) => item.id === details.itemValue)?.onSelect(), emit('command'))
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const effect1 = () => {
  emit('queryChange', query.value)
}
onMounted(effect1)
const effect2 = () => {
  api.value.highlightedValue === null &&
    firstEnabled.value !== undefined &&
    api.value.setHighlightValue(firstEnabled.value)
}
onMounted(effect2)
watch(() => api.value.highlightedValue ?? firstEnabled.value, effect2, { flush: 'post' })
</script>

<template>
  <div :class="styles.search">
    <Icon name="search" size="md" />
    <!-- input -->
    <input
      v-bind="api.getInputProps()"
      :class="styles.input"
      :aria-label="placeholder"
      @keydown="$event.key === 'Escape' && !composingKey($event) && api.setInputValue('')"
    />
    <Kbd>
      {{ escapeHint }}
    </Kbd>
  </div>
  <div :class="styles.body" data-dialog-part="body">
    <!-- list -->
    <ul
      v-bind="api.getContentProps()"
      :class="styles.listbox"
      :hidden="undefined"
      :aria-labelledby="undefined"
      aria-label="Suggestions"
    >
      <template v-for="(run, at) in runs" :key="run.map((item) => item.id).join(' ')">
        <template v-if="run[0]?.group === undefined">
          <template v-for="item in run" :key="`${query}/${item.id}`">
            <!-- item -->
            <li
              v-bind="api.getItemProps({ item: item, persistFocus: true })"
              :class="styles.item"
              :aria-labelledby="`${uid}-label-${item.id}`"
            >
              <span v-if="item.icon !== undefined" :class="styles.glyph">
                <Icon :name="item.icon" size="sm" />
              </span>
              <span :class="styles.label" :id="`${uid}-label-${item.id}`">
                {{ item.label }}
              </span>
              <span v-if="item.hint !== undefined" :class="styles.hint">
                <Kbd>
                  {{ item.hint }}
                </Kbd>
              </span>
            </li>
          </template>
        </template>
        <li v-else :class="styles.section" role="presentation">
          <span
            v-bind="api.getItemGroupLabelProps({ htmlFor: `${at}` })"
            :class="styles.groupLabel"
          >
            {{ run[0]?.group }}
          </span>
          <ul v-bind="api.getItemGroupProps({ id: `${at}` })" :class="styles.group">
            <template v-for="item in run" :key="`${query}/${item.id}`">
              <!-- item -->
              <li
                v-bind="api.getItemProps({ item: item, persistFocus: true })"
                :class="styles.item"
                :aria-labelledby="`${uid}-label-${item.id}`"
              >
                <span v-if="item.icon !== undefined" :class="styles.glyph">
                  <Icon :name="item.icon" size="sm" />
                </span>
                <span :class="styles.label" :id="`${uid}-label-${item.id}`">
                  {{ item.label }}
                </span>
                <span v-if="item.hint !== undefined" :class="styles.hint">
                  <Kbd>
                    {{ item.hint }}
                  </Kbd>
                </span>
              </li>
            </template>
          </ul>
        </li>
      </template>
    </ul>
    <div v-if="loading" :class="styles.rows" aria-hidden="true">
      <template v-for="skeleton in [0, 1, 2]" :key="skeleton">
        <div :class="styles.row">
          <Skeleton textStep="sm" />
        </div>
      </template>
    </div>
    <div v-if="showEmpty" :class="styles.empty" aria-hidden="true">
      {{ emptyMessage }}
    </div>
  </div>
  <div :class="styles.status" role="status" aria-live="polite">
    {{ announcement }}
  </div>
</template>
